1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { parseWranglerConfig, publishedDir, wranglerConfigPath, WRANGLER_CONFIGS } from '../lib.mjs';
3	
4	// WHY. The wrangler config is the whole boundary of what reaches a public URL: the
5	// release uploads `assets.directory` and nothing else, and the repo around it holds
6	// the vendored mount, the queue's workers and the packs. A widened or missing
7	// directory is not a broken build — the deploy succeeds and publishes the agent
8	// tooling, or publishes nothing, and neither looks wrong anywhere.
9	//
10	// SCOPE. The one wrangler config the release reads (root or one directory down,
11	// JSON or JSONC). A repo declaring this pack has said it deploys this way, so a
12	// missing config is a finding rather than a reason to stay quiet.
13	
14	const rule = {
15	  id: 'cloudflare-site/publishes-a-site-directory',
16	  severity: 'blocking',
17	  since: '2026-09-13',
18	  description: 'The wrangler config names a published subdirectory that exists, and pins a compatibility date',
19	  doc: 'packs/cloudflare-site/RULES.md',
20	  why: 'assets.directory is the only boundary between the published site and the repo holding the mount, the packs and the queue workers',
21	
22	  run(ctx) {
23	    const configPath = wranglerConfigPath(ctx.tracked);
24	    if (!configPath) {
25	      return [finding(rule, {
26	        file: WRANGLER_CONFIGS[0],
27	        what: 'no wrangler.json or wrangler.jsonc at the repo root or one directory down',
28	        fix: 'add the wrangler config the release reads — it names the tree to upload (assets.directory) and the custom domains to attach; a TOML config is a wrangler setup this pack does not read',
29	      })];
30	    }
31	
32	    const config = parseWranglerConfig(ctx.read(configPath));
33	    if (config === null) {
34	      return [finding(rule, {
35	        file: configPath,
36	        what: `${configPath} does not parse as JSON`,
37	        fix: 'fix the syntax — the release and these checks all read this file, and a config they cannot parse stops the release at the gate',
38	      })];
39	    }
40	
41	    const out = [];
42	    const dir = publishedDir(config, configPath);
43	    if (!dir) {
44	      out.push(finding(rule, {
45	        file: configPath,
46	        what: 'the config declares no assets.directory',
47	        fix: 'set assets.directory to the one tree the site publishes — without it wrangler deploy has no target at all',
48	      }));
49	    } else if (dir === '' || dir === '.' || dir === configPath.slice(0, Math.max(0, configPath.lastIndexOf('/')))) {
50	      out.push(finding(rule, {
51	        file: configPath,
52	        what: `assets.directory publishes ${dir === '' || dir === '.' ? 'the repo root' : dir}`,
53	        fix: 'point assets.directory at a subdirectory holding the site and nothing else — publishing the tree that holds it publishes the vendored mount, the packs and the queue workers to a public URL',
54	      }));
55	    } else if (!ctx.tracked.some((f) => f.startsWith(`${dir}/`))) {
56	      out.push(finding(rule, {
57	        file: configPath,
58	        what: `assets.directory names ${dir}, which holds no tracked file`,
59	        fix: `create ${dir} with the site in it, or point assets.directory at the tree that is actually published — a deploy of an empty directory serves a 404 to every visitor and reports success`,
60	      }));
61	    }
62	
63	    if (!config.compatibility_date) {
64	      out.push(finding(rule, {
65	        file: configPath,
66	        what: 'the config declares no compatibility_date',
67	        fix: 'pin compatibility_date, so the runtime a release lands on is a value in the repo rather than whatever the deploy day defaults to',
68	      }));
69	    }
70	
71	    return out;
72	  },
73	};
74	
75	export default rule;
