1	import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../../../engine/checks/helpers/code-scanning.mjs';
3	import { TEST_DIR } from '../../../../../vendoring/compute-vendor-set.mjs';
4	
5	// Phase 4 of #593: the rule that stops the class recurring by omission.
6	//
7	// `consumer-safe-changes.md` has always SAID that a change to a vendored
8	// contract must carry consumers across it. Nothing enforced that, and #555
9	// merged green while eleven consumer packs stopped validating — because the
10	// canon's own packs were updated in the same commit, and canon CI has nothing
11	// else to look at.
12	//
13	// So this is a check over the canon's OWN diff, not prose about the diff. It
14	// runs in the WORK scope: the branch's change is exactly what it judges, and
15	// judging the whole tree would be meaningless (the tree always contains a
16	// manifest field; the question is whether THIS change added one).
17	//
18	// WHAT IT CATCHES. A change that alters a contract every consumer holds a copy
19	// of, without either of the two things that carry consumers across:
20	//
21	//   a MIGRATION RECORD  — <flow>/migrations/<date>-<name>/migration.mjs, the
22	//                         mechanism that rewrites a member on its next converge
23	//   a REHEARSAL FIXTURE — vendoring/rehearsal/fixtures.mjs, which proves a
24	//                         consumer in that shape still converges green
25	//
26	// Either satisfies it. They answer different questions — "members are moved
27	// across" versus "members are unharmed" — and both are legitimate; a change that
28	// is genuinely additive needs only the second.
29	//
30	// DELIBERATELY NARROW. It triggers on three surfaces, each chosen because a
31	// consumer holds a copy of it and cannot be asked to change in the same commit:
32	//
33	//   pack-schema.mjs        the manifest vocabulary — #555's exact surface
34	//   a rule's `severity`    advisory -> blocking turns a member red overnight
35	//   either workflow stub   every member vendors it verbatim
36	//   a removed export       a member's local pack imports the mount by name (#1848)
37	//
38	// It does NOT fire on ordinary pack or engine edits. A rule that cried wolf on
39	// every canon commit would be turned off within a week, and then it would be
40	// worth nothing on the day it mattered.
41	const SCHEMA = 'engine/pack_loader/pack-schema.mjs';
42	// BOTH stubs: a member vendors the executor's workflow as verbatim as the
43	// scheduler's, and its event trigger names label strings literally — the surface a
44	// vocabulary change has to carry members across (#1119).
45	const STUBS = [
46	  'packs/claudinite-tasks/stubs/claudinite-scheduler.yml',
47	  'packs/claudinite-tasks/stubs/claudinite-executor.yml',
48	];
49	// A record folder, not the machinery beside it: registry/apply edits are engine
50	// work and carry no member across anything. A record lives under the flow that
51	// owns it — the engine's own, or one pack's — so both homes count (#768).
52	const MIGRATION_RECORD = /^(engine|packs\/[^/]+)\/migrations\/\d{4}-\d{2}-\d{2}-[^/]+\//;
53	const MIGRATIONS = '<engine|packs/*>/migrations/<date>-<name>/';
54	const FIXTURES = 'vendoring/rehearsal/fixtures.mjs';
55	// The canon's own local packs — repo-only content, outside every vendor set.
56	const LOCAL_PACKS = '.claudinite/local/packs';
57	
58	// The fourth surface (#1848). A member's own local packs import out of the mount —
59	// `.claudinite/shared/engine/checks/helpers/findings.mjs` is how a local rule builds a
60	// finding at all — so every name `engine/**` and `packs/**` export is a contract the
61	// canon has never seen the other side of. The engine root vendors WHOLESALE, so a
62	// dropped name does not degrade a member: the importing module throws at load, its
63	// pack fails to load, and the converge's self-test refuses the whole tree.
64	//
65	// Neither rehearsal can see it. The canary's local pack imports nothing out of
66	// `.claudinite/shared/` (a stated design property of its rules), and no fixture local
67	// pack does either — so both converge green whatever this surface does. #1750 dropped
68	// nine names from converge-wiring.mjs and left missingbulb/Shepherd#477 parked.
69	//
70	// A RE-EXPORT SHIM IS THE DISCHARGE, and it needs no mechanism of its own: a name
71	// still exported is not a removal. #1750 already gave three of its nine names exactly
72	// that. The other two answers stay available for a name that genuinely must go.
73	//
74	// Measured before widening, over the 60 most recent first-parent commits on main:
75	// 4 commits would have fired (1 engine, 3 packs). `packs/**` is in because the surface
76	// is structurally identical — Shepherd's fleet-issues-snapshot worker reaches four
77	// modules under `shared/packs/`.
78	//
79	// A PACK'S `test/` DIRECTORY IS NOT THAT SURFACE: the vendor set drops it whole, so no
80	// member holds any of it and nothing there is a name anybody can import. Excluded by
81	// the vendor set's own constant rather than by a second spelling of it, and by the
82	// DIRECTORY rather than by the `.test.mjs` suffix — which is the distinction
83	// `compute-vendor-set.mjs` states for itself: "the name is the rule, so a fixture, a
84	// helper or a golden file a test needs stops shipping with it instead of being one
85	// `*.test.mjs` short of the exclusion". A harness beside its scenarios is exactly that
86	// helper, and a suffix-only exclusion reads rewriting one as a fleet migration.
87	const VENDORED_MODULE = /^(engine|packs)\//;
88	const PACK_TEST_DIR = new RegExp(`^packs/[^/]+/${TEST_DIR}/`);
89	
90	// The names a module exports, by every form the corpus writes: a declaration
91	// (`export const|let|var|function|async function|class NAME`) and an export list
92	// (`export { a, b as c }`, where the exported name is what an importer must write).
93	// `export default` is out: a default is imported by position, not by name.
94	//
95	// Comments are stripped first — a commented-out export is not a contract, and the
96	// engine's own string-aware remover is what tells a `//` inside a string from one that
97	// opens a comment.
98	const EXPORT_DECL = /^\s*export\s+(?:async\s+)?(?:function\*?|const|let|var|class)\s+([A-Za-z_$][\w$]*)/gm;
99	const EXPORT_LIST = /^\s*export\s*\{([^}]*)\}/gm;
100	export function exportedNames(text) {
101	  const names = new Set();
102	  if (typeof text !== 'string') return names;
103	  const src = stripComments(text);
104	  for (const m of src.matchAll(EXPORT_DECL)) names.add(m[1]);
105	  for (const m of src.matchAll(EXPORT_LIST)) {
106	    for (const part of m[1].split(',')) {
107	      const spec = part.trim();
108	      if (!spec) continue;
109	      const renamed = /\bas\s+([A-Za-z_$][\w$]*)$/.exec(spec);
110	      names.add(renamed ? renamed[1] : spec.split(/\s+/)[0]);
111	    }
112	  }
113	  return names;
114	}
115	
116	// Present in the base, absent from the head. A head that cannot be read is the file
117	// deleted — every name it exported is gone, which is the shape a whole-module removal
118	// takes and the one a diff-line rule cannot see. A base that cannot be read is a file
119	// this change ADDED, and an addition removes nothing.
120	export function removedExports(file, head, base) {
121	  if (!VENDORED_MODULE.test(file) || MIGRATION_RECORD.test(file) || PACK_TEST_DIR.test(file)) return [];
122	  if (typeof base !== 'string') return [];
123	  const now = exportedNames(head);
124	  return [...exportedNames(base)].filter((name) => !now.has(name));
125	}
126	
127	// A comment is inert on every surface this rule watches: a member vendors the bytes
128	// verbatim and nothing reads the prose in them, so rewriting one carries nobody
129	// anywhere and asking for a migration record would be the cried-wolf firing this
130	// rule is narrowed to avoid. Both sides must be readable to reach that conclusion —
131	// an unreadable file stays a contract surface, so the fail-safe answer is the one a
132	// missing file gets.
133	//
134	// `#` only opens a comment at line start or after whitespace, which is what keeps a
