  id: 'cloudflare-site/internal-links-omit-html-extension',
  severity: 'blocking',
  since: '2026-09-23',
  description: 'An internal link inside the published tree names the page\'s canonical path, never the .html file',
  doc: 'packs/cloudflare-site/RULES.md',
