1	// What the repo's own wrangler config says about the deployment: which tree is
2	// published, which hostnames the Worker claims, and how it canonicalizes a page's
3	// URL. Every other file in this pack asks these questions, and none of them asks the
4	// repo to repeat the answers as config - the config file wrangler already reads is
5	// the one source.
6	//
7	// JSON only (`wrangler.json`/`wrangler.jsonc`). A TOML config is a legitimate
8	// wrangler setup and simply not one this pack reads: parsing a second
9	// configuration language to answer two questions buys nothing that moving the
10	// config does not, and `publishes-a-site-directory` says so where a repo meets it.
11	
12	// The config filenames wrangler resolves, in its own precedence order.
13	export const WRANGLER_CONFIGS = ['wrangler.json', 'wrangler.jsonc'];
14	
15	// The config in `paths`, at the repo root or one directory down — the same reach
16	// the cloudflare-workers pack fingerprints on, so a stray config in a fixture or
17	// example tree deeper in the tree is not mistaken for the deployment's.
18	export function wranglerConfigPath(paths = []) {
19	  const candidates = paths.filter((p) => {
20	    const parts = p.split('/');
21	    return parts.length <= 2 && WRANGLER_CONFIGS.includes(parts[parts.length - 1]);
22	  });
23	  // Shallowest first, then the extension order wrangler itself prefers.
24	  candidates.sort((a, b) => a.split('/').length - b.split('/').length
25	    || WRANGLER_CONFIGS.indexOf(a.split('/').pop()) - WRANGLER_CONFIGS.indexOf(b.split('/').pop()));
26	  return candidates[0] ?? null;
27	}
28	
29	// JSONC to JSON: drop `//` and `/* */` comments that are not inside a string.
30	// Hand-written because the whole need is two comment forms over a file wrangler
31	// itself accepts, and a dependency for that is a dependency to keep.
32	export function stripJsonComments(text) {
33	  let out = '';
34	  let inString = false;
35	  let inLine = false;
36	  let inBlock = false;
37	  for (let i = 0; i < text.length; i += 1) {
38	    const c = text[i];
39	    const next = text[i + 1];
40	    if (inLine) { if (c === '\n') { inLine = false; out += c; } continue; }
41	    if (inBlock) { if (c === '*' && next === '/') { inBlock = false; i += 1; } continue; }
42	    if (inString) {
43	      out += c;
44	      if (c === '\\') { out += next ?? ''; i += 1; } else if (c === '"') inString = false;
45	      continue;
46	    }
47	    if (c === '"') { inString = true; out += c; continue; }
48	    if (c === '/' && next === '/') { inLine = true; i += 1; continue; }
49	    if (c === '/' && next === '*') { inBlock = true; i += 1; continue; }
50	    out += c;
51	  }
52	  return out;
53	}
54	
55	// The parsed config, or null when it is absent or unparseable — the callers all
56	// have something to say about that themselves.
57	export function parseWranglerConfig(text) {
58	  if (typeof text !== 'string') return null;
59	  try { return JSON.parse(stripJsonComments(text)); } catch { return null; }
60	}
61	
62	// The published tree, as a repo-relative path: `assets.directory` resolved against
63	// the directory holding the config, exactly as wrangler resolves it.
64	export function publishedDir(config, configPath = 'wrangler.json') {
65	  const dir = config?.assets?.directory;
66	  if (typeof dir !== 'string' || !dir.trim()) return null;
67	  const base = configPath.includes('/') ? `${configPath.slice(0, configPath.lastIndexOf('/'))}/` : '';
68	  const normalized = dir.replace(/^\.\//, '').replace(/\/+$/, '');
69	  return `${base}${normalized}`;
70	}
71	
72	// Which spelling of an HTML page's URL the deploy treats as canonical, and so which
73	// spellings it 307s there: `assets.html_handling`, wrangler's own default where the
74	// config leaves it unset. `none` is the mode that redirects nothing, and there the
75	// `.html` spelling is the only one that resolves to the page at all.
76	// https://developers.cloudflare.com/workers/static-assets/routing/advanced/html-handling/
77	export const DEFAULT_HTML_HANDLING = 'auto-trailing-slash';
78	export function htmlHandling(config) {
79	  const mode = config?.assets?.html_handling;
80	  return typeof mode === 'string' && mode.trim() ? mode.trim() : DEFAULT_HTML_HANDLING;
81	}
82	
83	// The hostnames the deploy attaches as custom domains — the ones a visitor types,
84	// and the ones a record inherited from a previous host can block or shadow.
85	export function claimedHostnames(config) {
86	  const routes = Array.isArray(config?.routes) ? config.routes : [];
87	  return routes
88	    .filter((r) => r && r.custom_domain === true && typeof r.pattern === 'string')
89	    .map((r) => r.pattern);
90	}
91	
92	// The Cloudflare Web Analytics beacon token is public — it ships in the client — so it
93	// rides a repository VARIABLE and is substituted into the copy being uploaded, never
94	// into the commit. A loader carrying this placeholder no-ops while it is still in
95	// place. Here rather than in the release worker because the check that keeps a real
96	// token out of the tree names it too, and a check may not drag a task's worker (and
97	// its imports) into every sweep.
98	export const BEACON_PLACEHOLDER = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';

